 home(){this.controls.reset();disposeGroup(this.labels);}
 sprite(text){const c=document.createElement('canvas');c.width=384;c.height=64;const ctx=c.getContext('2d');ctx.fillStyle='#102332ed';ctx.fillRect(0,0,384,64);ctx.font='26px sans-serif';ctx.textAlign='center';ctx.fillStyle='white';ctx.fillText(text,192,42);const tex=new T.CanvasTexture(c);const s=new T.Sprite(new T.SpriteMaterial({map:tex,depthTest:false}));s.scale.set(28,4.7,1);s.renderOrder=20;return s;}
 errorSprite(count){const c=document.createElement('canvas');c.width=192;c.height=192;const x=c.getContext('2d'),gradient=x.createRadialGradient(70,55,8,96,96,73);gradient.addColorStop(0,'#ff5757');gradient.addColorStop(.55,'#f01421');gradient.addColorStop(1,'#bf0010');x.shadowColor='#31000788';x.shadowBlur=14;x.fillStyle=gradient;x.beginPath();x.arc(91,91,69,0,Math.PI*2);x.fill();x.shadowBlur=0;x.fillStyle='#fff';x.font='900 104px system-ui';x.textAlign='center';x.textBaseline='middle';x.fillText('!',91,93);if(count>1){x.fillStyle='#fff';x.beginPath();x.arc(147,145,29,0,Math.PI*2);x.fill();x.strokeStyle='#d30016';x.lineWidth=7;x.stroke();x.fillStyle='#c90014';x.font='800 28px system-ui';x.fillText(String(count),147,146);}const tex=new T.CanvasTexture(c),s=new T.Sprite(new T.SpriteMaterial({map:tex,transparent:true,depthTest:false}));s.scale.set(28,28,1);s.renderOrder=80;return s;}
 showTerminals(d){disposeGroup(this.labels);for(const t of d.terminalObjects){const label=this.sprite(t.physicalNumber?`${t.physicalNumber} ${t.displayNumber}`:t.displayNumber);label.position.set(...t.positionMm);label.position.y+=4.8;label.position.z+=5;this.labels.add(label);}const name=this.sprite(d.id+' '+d.model);name.scale.set(100,16,1);name.position.set(d.centerMm[0],d.centerMm[1]+d.displaySizeMm[1]/2+16,d.displaySizeMm[2]+4);this.labels.add(name);}
 highlight(ids=[],wireIds=[]){disposeGroup(this.selection);for(const id of ids){const t=this.problem.terminalMap[id];if(!t)continue;const ring=new T.Mesh(new T.TorusGeometry(4,.7,6,20),new T.MeshBasicMaterial({color:'#ff694a',depthTest:false}));ring.position.set(...t.positionMm);ring.position.z+=3;ring.renderOrder=25;this.selection.add(ring);}for(const id of wireIds){const w=this.connections.find(w=>w.id===id);if(!w)continue;const g=wireMesh(this.problem,w);g.traverse(o=>{if(o.material){o.material.color.set('#ff694a');o.material.depthTest=false;}});g.renderOrder=22;this.selection.add(g);}}
 focusItems(ids=[],wireIds=[]){
  const terminalIds=new Set(ids);for(const id of wireIds){const w=this.connections.find(w=>w.id===id);if(w){terminalIds.add(w.from);terminalIds.add(w.to);}}
  const points=[...terminalIds].map(id=>this.problem.terminalMap[id]?.positionMm).filter(Boolean).map(v=>new T.Vector3(...v));if(!points.length)return;
  const box=new T.Box3().setFromPoints(points).expandByScalar(18),center=box.getCenter(new T.Vector3()),size=box.getSize(new T.Vector3()),span=Math.max(size.x,size.y,size.z,45);
  const direction=this.camera.position.clone().sub(this.controls.target).normalize();if(!Number.isFinite(direction.x)||direction.lengthSq()===0)direction.set(0,-.25,1);this.controls.target.copy(center);this.camera.position.copy(center).add(direction.multiplyScalar(Math.max(85,span*2.4)));this.controls.update();
  this.highlight(ids,wireIds);
 }
 setErrorMarkers(groups=[]){disposeGroup(this.errorMarkers);this.errorHits=[];for(const group of groups){const wire=this.connections.find(w=>w.id===group.anchorWireId),device=this.problem.devices.find(d=>d.id===group.anchorDeviceId);let pos=null;if(device)pos=new T.Vector3(device.centerMm[0],device.centerMm[1],Math.max(device.displaySizeMm[2],28)+32);else if(wire){const a=this.problem.terminalMap[wire.from]?.positionMm,b=this.problem.terminalMap[wire.to]?.positionMm;if(a&&b)pos=new T.Vector3((a[0]+b[0])/2,(a[1]+b[1])/2,Math.max(a[2],b[2])+34);}else if(group.terminalIds?.[0]&&this.problem.terminalMap[group.terminalIds[0]])pos=new T.Vector3(...this.problem.terminalMap[group.terminalIds[0]].positionMm).add(new T.Vector3(0,0,30));if(!pos)continue;group.markerPosition=pos.toArray();const marker=this.errorSprite(group.count);marker.position.copy(pos);marker.userData.error=group;this.errorMarkers.add(marker);const hit=new T.Mesh(new T.SphereGeometry(13,12,8),new T.MeshBasicMaterial({transparent:true,opacity:0,depthTest:false}));hit.position.copy(pos);hit.userData.error=group;hit.renderOrder=81;this.errorMarkers.add(hit);this.errorHits.push(hit);}}
 markErrorViewed(errorId){this.errorMarkers.traverse(o=>{if(o.userData.error?.id===errorId&&o.material&&o.type==='Sprite'){o.material.transparent=true;o.material.opacity=.52;}});}
 setConnections(connections){this.connections=connections;disposeGroup(this.wires);this.wireTargets=[];const incident=new Map();for(const w of connections)for(const side of ['from','to']){if(!incident.has(w[side]))incident.set(w[side],[]);incident.get(w[side]).push(w.id);}
  for(const w of connections){const mounts={};for(const id of [w.from,w.to])mounts[id]={paired:incident.get(id).length>1,index:incident.get(id).indexOf(w.id)};const g=wireMesh(this.problem,w,null,mounts);g.traverse(o=>{if(o.isMesh&&!o.userData.terminal){o.userData.connection=w;this.wireTargets.push(o);}});this.wires.add(g);}
 }
 setDraft(draft,end){this.draft=draft;this.looseEnd=end;this.drawDraft();}
 drawDraft(){disposeGroup(this.draftGroup);if(!this.draft?.source)return;const d=this.draft,target=d.destination?.positionMm??this.pointer;this.draftGroup.add(wireMesh(this.problem,{from:d.source.id,...d.material,ends:{from:d.ends?.from??d.material.end,to:d.ends?.to??this.looseEnd},via:d.via},target));}
 showPreparation(stage,material,draft=null){disposeGroup(this.preparation);if(stage==='전선 선택'||stage==='전선')return;const g=new T.Group();g.position.set(-230,-235,50);g.scale.setScalar(.35);const color=material.color==='갈색'?'#8b4b24':material.color==='검은색'?'#202733':material.color==='회색'?'#85909d':material.color==='녹색-노란색'?'#269957':'#e0b600';block(g,[3,42,3],[0,-21,0],color);block(g,[1.3,10,1.3],[0,5,0],'#bd7a42');const side=stage.startsWith('끝측')?'to':'from',end=draft?.ends?.[side]??material.end;if(end?.tube===true){const tube=cylinder(g,2.2,9,[0,-1,0],'#3c87c2');tube.rotation.set(0,0,0);}if(end?.crimp){const lug=lugMesh(end);lug.position.set(0,12,0);g.add(lug);}this.prepStarted=performance.now();this.preparation.add(g);}
